"OLAYLAR_T5_1000B:1256-01-01:0":{"b": ["იერუსალიმი კვლავ აიუბიდებს გადაეცა", "fdeedd4a"], "d": ["პალესტინა და იერუსალიმი კვლავ სირიელი აიუბიდების ხელში გადავიდა.", "46a6e2a9"]},
"OLAYLAR_T5_1000B:1260-03-01:0":{"b": ["მონღოლებმა დამასკო აიღეს", "430bdfea"], "d": ["ჰულაგუს სირიის ლაშქრობისას დამასკო მონღოლებს გადაეცა.", "407e5d3f"]},
"OLAYLAR_T5_1000B:1260-09-03:0":{"b": ["აინ-ჯალუთის ბრძოლა: დამასკო და იერუსალიმი მამლუქებს გადაეცა", "40ebd7b7"], "d": ["ქუთუზმა მონღოლები აინ-ჯალუთთან დაამარცხა (25 რამადანი 658 / 1260 წლის 3 სექტემბერი); სირიის დიდი ნაწილი, დამასკო და იერუსალიმი მამლუქთა ხელში გადავიდა, აიუბიდთა დინასტია დასრულდა.", "619c8015"]},
"OLAYLAR_T5_1000B:1261-06-09:0":{"b": ["ბაიბარსმა აბასიანთა სახალიფო კაიროში აღადგინა — მექა და მედინა მამლუქებს დაუკავშირდა", "a5128a1e"], "d": ["ბაიბარსმა ბაღდადის დაცემისგან გადარჩენილი აბასიანი აჰმადი კაიროში ხალიფად გამოაცხადა და ერთგულება შეჰფიცა; სახალიფოს მფარველის სტატუსით ორი წმინდა ქალაქიც მამლუქთა უზენაესობას დაუკავშირა. დღე სახალიფოს აღდგენისაა; მექისა და მედინის დაკავშირების დღე წყაროში არ არის (ქვედა ზღვარი).", "638d550a"]},
"OLAYLAR_T5_1000B:1261-07-25:0":{"b": ["იზნიკის ნაწილები სტამბოლში შევიდნენ — ბიზანტიის იმპერია აღდგა", "81741490"], "d": ["იზნიკის ნაწილები 1261 წლის 25 ივლისს სტამბოლში შევიდნენ და ლათინთა ბატონობას ბოლო მოუღეს; ლასკარისთა (იზნიკის) სახელმწიფოს მიწები — ბურსა, იზმირი, ჩიმპე, ედირნე, სალონიკი — კვლავ ბიზანტიის იმპერია გახდა. ატლასი ამ წერტილებზე 1261 წლამდე იზნიკის იმპერიის პერიოდს მხოლოდ იმათთვის აჩვენებს, რომლებიც წყაროში სახელით მოიხსენიება.", "b389b508"]},
"OLAYLAR_T5_1000B:1271-01-01:0":{"b": ["კარლ ანჟუელმა დურესი და კრუია აიღო", "082a86b8"], "d": ["ანჟუელთა დინასტიის კარლმა 1271–1272 წლებში დურესი და კრუია აიღო და ძველი ციხე ხელახლა ააგებინა.", "e9f84d14"]},
"OLAYLAR_T5_1000B:1284-01-01:0":{"b": ["სიცილიელებმა ჯერბას კუნძული დაიკავეს", "daab5ad2"], "d": ["ჯერბას კუნძული 683 (1284-85) წელს სიცილიელებმა დაიკავეს; ჯერ პაპის მამული იყო, შემდეგ კი სიცილიის სამეფოს დაექვემდებარა.", "691035b3"]}
